        tempx = xpos{view}(:,:,feat);
        tempx(isnan(tempx)) = mux;
        xpos{view}(:,:,feat) = tempx;
        tempy = ypos{view}(:,:,feat);
        tempy(isnan(tempy)) = muy;
        ypos{view}(:,:,feat) = tempy;

        ct = ct + 1;

    end
end

