import h5py, numpy as np
def strof(f,ref):
    d=np.array(f[ref])
    return ''.join(chr(c) for c in d.flatten())
for p in ['/app/data/Ephys_Behavior/data_structure_JEB19_2023-04-18.mat','/app/data/Ephys_Behavior/data_structure_JEB6_2021-04-18.mat']:
