                    print(' ',k,[strof(f,r) for r in np.array(it).flatten()])
                elif it.dtype==np.uint16:
                    print(' ',k, ''.join(chr(c) for c in np.array(it).flatten()))
                else:
                    print(' ',k, np.array(it).flatten()[:10])
            except Exception as e: print(' ',k,'err',e)
    if 'meta' in o:
        print('meta keys', list(o['meta'].keys()) if isinstance(o['meta'],h5py.Group) else o['meta'])
